<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import type {PcApi} from '../api';
import {BusinessOperations} from '../business-pending';
import SourceFiles from './SourceFiles.vue';
import {HistoricalController,createHistoricalState,historicalBusy,historicalDirty,historicalWritable,historicalStatus,historicalCoverage,historicalToday,historicalOperationTarget,assertHistoricalReceipt,moneyDifference,type HistoricalOrder,type HistoricalSupplyStatus} from '../../../../packages/historical-client/src';
const props=defineProps<{api:Pick<PcApi,'get'|'post'|'write'>;userId:string;admin:boolean;initialOrderId?:string;locked?:boolean}>();
const emit=defineEmits<{(e:'busy-changed',value:boolean):void;(e:'failure',value:unknown):void;(e:'openFinance',target:{orderId:string;receivableId?:string}):void}>();
const state=reactive(createHistoricalState(props.admin)),ack=ref(false),recovering=ref(false),notFound=ref(false),storageError=ref(''),recoveryError=ref(''),childBusy=ref(false),sources=ref<InstanceType<typeof SourceFiles>|null>(null);
let operations:Pick<BusinessOperations,'pending'|'mutate'|'check'|'retry'>|null=null,recoveredOrderId='';
try{operations=reactive(new BusinessOperations(props.userId,async<T>(path:string)=>{const r=await props.api.get<T>(path);if(path.startsWith('/operations/')&&(r as any)?.status==='committed'&&operations?.pending){assertHistoricalReceipt(operations.pending,(r as any).result);recoveredOrderId=(r as any).result?.orderId||'';}return r;},async<T>(path:string,method:'POST'|'PUT'|'PATCH',body:unknown,key:string)=>{const r=await props.api.write<T>(path,method,body,key);if(operations?.pending)assertHistoricalReceipt(operations.pending,r);return r;},{getItem:key=>localStorage.getItem('history-'+key),setItem:(key,value)=>localStorage.setItem('history-'+key,value),removeItem:key=>localStorage.removeItem('history-'+key)}));}catch(e){storageError.value=(e as Error).message;}
const controller=new HistoricalController(p=>props.api.get(p),(label,path,method,body)=>{if(!operations)throw new Error(storageError.value||'本机操作资料不可用，暂不能提交。');return operations.mutate<HistoricalOrder>(label,path,method,body);},state,e=>emit('failure',e));
const busy=computed(()=>historicalBusy(state)||recovering.value||childBusy.value),dirty=computed(()=>historicalDirty(state)),blocked=computed(()=>!!props.locked||busy.value||!!operations?.pending||!!storageError.value),navigationLocked=computed(()=>blocked.value||dirty.value||!!state.review||state.correctionOpen),writable=computed(()=>historicalWritable(state)),draftWritable=computed(()=>writable.value&&state.detail?.verificationStatus!=='verified'),fieldsLocked=computed(()=>blocked.value||!draftWritable.value||!!state.review),pages=computed(()=>Math.max(1,Math.ceil((state.page?.total||0)/(state.page?.pageSize||20)))),coverage=computed(()=>historicalCoverage(state.form.lines.map(l=>({...l,quantity:l.quantity||null,confirmedQuantity:l.confirmedQuantity||null,unitPrice:l.unitPrice||null})),state.form.confirmedDate||null)),files=computed(()=>sources.value?.sourceFiles||[]),evidence=computed(()=>state.correctionOpen?state.correction.evidenceFileIds:state.form.evidenceFileIds);
const statuses=[['','全部核实状态'],['pending_verification','待核实'],['verified','已核实'],['draft','草稿']];
watch(()=>busy.value||dirty.value||!!state.review||state.correctionOpen||!!operations?.pending,v=>emit('busy-changed',v),{immediate:true,flush:'sync'});watch(()=>state.review,()=>{ack.value=false;});
function guard(work:()=>unknown){if(blocked.value)return;try{state.error='';work();}catch(e){state.error=(e as Error).message;}}
async function safely(work:()=>Promise<unknown>){if(blocked.value)return;try{await work();}catch(e){state.error=(e as Error).message;}}
function supply(index:number,event:Event){guard(()=>controller.setSupply(index,(event.target as HTMLSelectElement).value as HistoricalSupplyStatus));}
function toggleEvidence(id:string){if(blocked.value||state.review||!writable.value||state.detail?.verificationStatus==='verified'&&!state.correctionOpen)return;const list=evidence.value,index=list.indexOf(id);index<0?list.push(id):list.splice(index,1);}
async function refresh(){if(navigationLocked.value)return;await safely(()=>state.detail?controller.open(state.detail.orderId):controller.bootstrap());}
async function openAfterRecovery(orderId?:string){controller.discard();if(orderId)await controller.open(orderId,true);else{state.mode='list';await controller.list();}state.notice=state.error?'原操作已确认提交，最新资料读取失败，请重试。':'原操作已确认提交，已读取最新历史资料。';}
async function recover(retry=false){if(props.locked||busy.value||!operations?.pending)return;const original=operations.pending,target=historicalOperationTarget(original);recovering.value=true;recoveryError.value='';try{const result=retry?await operations.retry<HistoricalOrder>():null,status=retry?'committed':await operations.check();notFound.value=status==='not_found';if(status==='committed'){recovering.value=false;await openAfterRecovery(result?.orderId||target?.orderId||recoveredOrderId||undefined);}}catch(e){recoveryError.value=(e as Error).message;emit('failure',e);}finally{recovering.value=false;}}
async function commit(){if(blocked.value||!ack.value)return;try{await controller.commit();}catch{/* original input and pending operation remain available */}}
function discard(){if(blocked.value)return;controller.discard();}
function finance(){const o=state.detail;if(o&&!navigationLocked.value)emit('openFinance',{orderId:o.orderId,...o.receivable?{receivableId:o.receivable.id}:{}});}
function beforeLeave(e:BeforeUnloadEvent){if(dirty.value||state.review||operations?.pending||childBusy.value){e.preventDefault();e.returnValue='';}}
defineExpose({refresh,openAfterRecovery,canLeave:()=>!busy.value&&!dirty.value&&!state.review&&!state.correctionOpen&&!operations?.pending&&(sources.value?.canLeave()??true)});
onMounted(async()=>{window.addEventListener('beforeunload',beforeLeave);await controller.bootstrap();if(props.initialOrderId)await controller.open(props.initialOrderId);});
watch(()=>props.initialOrderId,id=>{if(id&&!navigationLocked.value)void controller.open(id);});
onBeforeUnmount(()=>{window.removeEventListener('beforeunload',beforeLeave);controller.dispose();emit('busy-changed',false);});
</script>
<template>
 <div class="historical-workspace">
  <div class="heading"><div><p class="eyebrow">专用历史来源 · 仅内部可见</p><h1>历史纸单补录与核实</h1><p class="muted">保存旧资料，核实后纳入台账与统计。原账期、供货结果及实际日期未知时保留未知。</p></div><span class="scope">{{admin?'管理员只读':'当前订单负责人处理'}}</span></div>
  <p v-if="storageError" class="error" role="alert">{{storageError}}</p>
  <section v-if="operations?.pending" class="recovery"><strong>上次历史补录操作结果待核对</strong><p>原输入及操作标识已保存，请先核对。重新提交沿用原请求，不会重新生成一笔。</p><div class="actions"><button :disabled="busy||locked" @click="recover()">核对原操作结果</button><button v-if="notFound" :disabled="busy||locked" @click="recover(true)">按原请求重新提交</button></div><p v-if="notFound">暂未找到已提交结果，可按原请求重试。</p><p v-if="recoveryError" class="error">{{recoveryError}}</p></section>
  <p v-if="state.error" class="error" role="alert">{{state.error}}</p><p v-if="state.notice" class="notice" role="status">{{state.notice}}</p><p v-if="busy" class="muted" role="status">正在读取或提交，请稍候…</p>
  <div v-if="dirty||state.review||state.correctionOpen" class="unsaved"><span>本次内容尚未提交，切换前请保存或放弃修改。</span><button :disabled="blocked" @click="discard">放弃本次修改</button></div>
  <template v-if="state.mode==='list'">
   <form class="filters" @submit.prevent="safely(()=>controller.list())"><label>医院<select v-model="state.filters.hospitalId" :disabled="blocked"><option value="">全部可查看医院</option><option v-for="h in state.hospitals" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label>核实状态<select v-model="state.filters.verificationStatus" :disabled="blocked"><option v-for="s in statuses" :key="s[0]" :value="s[0]">{{s[1]}}</option></select></label><label class="keyword">订单 / 药品 / 规格<input v-model="state.filters.keyword" maxlength="100" :disabled="blocked" placeholder="输入关键字"/></label><button class="primary" type="submit" :disabled="blocked">查询</button><button v-if="!admin" type="button" :disabled="blocked" @click="guard(()=>controller.newDraft())">＋ 新建历史补录</button></form>
   <div v-if="state.page" class="result-head"><span>共 {{state.page.total}} 单</span><span>数据截止 {{state.page.asOf.replace('T',' ').slice(0,19)}} UTC · 金额单位：元</span></div>
   <div class="table-scroll"><table class="list-table"><thead><tr><th>医院 / 历史订单</th><th>实际接收 / 原账期</th><th>核实状态</th><th>当前金额 / 有效已收</th><th>操作</th></tr></thead><tbody><tr v-for="o in state.page?.items||[]" :key="o.orderId"><td><strong>{{o.hospitalName}}</strong><small>{{o.orderNo}}{{o.originalOrderNo?' · 原编号 '+o.originalOrderNo:''}}</small></td><td>{{o.receivedDate||'待核实'}}<small>{{o.originalTermDays===null?'原账期待核实':o.originalTermDays+' 自然日'}}</small></td><td>{{historicalStatus(o)}}<small>{{o.writable&&!admin?'当前负责，可处理':'只读查阅'}}</small></td><td>{{o.finalAmount===null?'待核实':o.finalAmount+' 元'}}<small>有效已收 {{o.receivable?o.receivable.paid+' 元':'核实后入账'}}</small></td><td><button :disabled="navigationLocked" @click="safely(()=>controller.open(o.orderId))">查看 / 处理 →</button></td></tr><tr v-if="state.page&&!state.page.items.length"><td colspan="5" class="empty">暂无符合筛选的历史补录。</td></tr></tbody></table></div>
   <div v-if="state.page" class="pagination"><span>第 {{state.page.page}} / {{pages}} 页</span><button :disabled="navigationLocked||state.page.page<=1" @click="safely(()=>controller.list((state.page?.page||1)-1))">上一页</button><button :disabled="navigationLocked||state.page.page>=pages" @click="safely(()=>controller.list((state.page?.page||1)+1))">下一页</button></div>
  </template>
  <template v-else-if="!state.accessBlocked">
   <div class="actions"><button :disabled="navigationLocked" @click="safely(()=>controller.home())">← 返回历史补录列表</button><button :disabled="navigationLocked" @click="refresh">载入最新保存稿</button><button v-if="state.detail?.receivable" :disabled="navigationLocked" @click="finance">账期 / 催收异常 →</button></div>
   <div class="record-heading"><h2>{{state.detail?state.detail.hospitalName+' · '+state.detail.orderNo:'新建历史补录'}}</h2><span v-if="state.detail">{{historicalStatus(state.detail)}} · 版本 {{state.detail.version}}</span></div>
   <p v-if="!writable" class="notice">当前记录只读，可查阅原始资料及每次核实和金额更正记录。</p>
   <p v-if="state.conflict" class="notice">资料版本发生变化，本次输入已保留。放弃本次修改后可载入最新保存稿；请核对差异再重新填写。</p>
   <div class="form-layout"><div class="main-form">
    <section><h3>01　订单与当时账期</h3><div class="form-grid"><label>医院 *<select v-model="state.form.hospitalId" :disabled="fieldsLocked||!!state.detail"><option value="">请选择当前负责医院</option><option v-for="h in state.hospitals" :key="h.id" :value="h.id">{{h.name}}</option><option v-if="state.detail&&!state.hospitals.some(h=>h.id===state.detail?.hospitalId)" :value="state.detail.hospitalId">{{state.detail.hospitalName}}</option></select></label><label>原纸单编号<input v-model="state.form.originalOrderNo" maxlength="100" :disabled="fieldsLocked" placeholder="未知留空"/></label><label>实际接收日期 *<input v-model="state.form.receivedDate" type="date" :max="historicalToday()" :disabled="fieldsLocked"/></label><label>原约定账期 / 自然日 *<input v-model="state.form.originalTermDays" inputmode="numeric" maxlength="4" :disabled="fieldsLocked" placeholder="未知留空，不套用默认账期"/></label><label>实际确认 / 知悉日期<input v-model="state.form.confirmedDate" type="date" :max="historicalToday()" :disabled="fieldsLocked"/></label><label>原经办人<input v-model="state.form.originalHandler" maxlength="200" :disabled="fieldsLocked" placeholder="未知留空"/></label></div><p class="muted">实际业务日期与系统补录日期分别留存；原账期未知时不能入账或推定到期日。</p></section>
    <section><div class="section-heading"><h3>02　采购药品与数量</h3><button v-if="draftWritable" :disabled="fieldsLocked||state.form.lines.length>=200" @click="guard(()=>controller.addLine())">＋ 增加药品</button></div><p class="muted">最多 200 行；仅 kg。单价与供货结果分别核实，未知结果不按采购量补齐。</p><div class="table-scroll"><table class="lines-table"><thead><tr><th>品名 *</th><th>规格</th><th>需求 kg *</th><th>供货状态</th><th>确认 kg</th><th>最终单价 / 元</th><th v-if="draftWritable">操作</th></tr></thead><tbody><tr v-for="(l,i) in state.form.lines" :key="l.id||i"><td><input v-model="l.name" :aria-label="'第 '+(i+1)+' 行品名'" maxlength="100" :disabled="fieldsLocked"/></td><td><input v-model="l.spec" aria-label="规格" maxlength="200" :disabled="fieldsLocked"/></td><td><input v-model="l.quantity" aria-label="需求 kg" inputmode="decimal" :disabled="fieldsLocked" placeholder="待核实"/></td><td><select :value="l.supplyStatus" :disabled="fieldsLocked" aria-label="供货状态" @change="supply(i,$event)"><option value="unknown">未知</option><option value="priced">有供货依据</option><option value="missing">明确全部缺货</option></select></td><td><input v-model="l.confirmedQuantity" aria-label="确认 kg" inputmode="decimal" :disabled="fieldsLocked||l.supplyStatus!=='priced'" placeholder="未知留空"/></td><td><input v-model="l.unitPrice" aria-label="最终单价" inputmode="decimal" :disabled="fieldsLocked||l.supplyStatus==='missing'" placeholder="未知留空"/></td><td v-if="draftWritable"><button :disabled="fieldsLocked" @click="guard(()=>controller.removeLine(i))">移除</button></td></tr></tbody></table></div></section>
    <section><h3>03　最终金额与历史已收</h3><div class="form-grid"><label>历史最终确认金额 / 元 *<input v-model="state.form.finalAmount" inputmode="decimal" :disabled="fieldsLocked" placeholder="允许 0，未知留空"/></label><label>截至补录时累计已收 / 元 *<input v-model="state.form.openingPaidAmount" inputmode="decimal" :disabled="fieldsLocked" placeholder="未收明确填 0，未知留空"/></label></div><p class="muted">历史累计已收不虚构逐笔支付日期；0 元不创建回款记录。后续新回款到台账逐笔登记，避免重复记旧款。</p></section>
    <section><h3>04　首次核实依据与说明</h3><label>核实依据 *<textarea v-model="state.form.verificationBasis" maxlength="2000" :disabled="fieldsLocked" placeholder="医院留存账本、对账资料或其他核实依据"></textarea></label><label>核实说明 *<textarea v-model="state.form.verificationNote" maxlength="2000" :disabled="fieldsLocked" placeholder="说明核实的事实，以及仍未知的逐行结果或实际日期"></textarea></label><p class="muted">两项文字核实时必填；纸单遗失可无附件。</p></section>
    <section v-if="state.detail"><SourceFiles :key="state.detail.orderId" ref="sources" :api="api" :user-id="userId" :reference="{kind:'historical_order',orderId:state.detail.orderId}" :readonly="!writable||state.detail.verificationStatus==='verified'&&!state.correctionOpen" :locked="!!locked||state.working||recovering||!!operations?.pending||!!state.review" @busy-changed="childBusy=$event" @failure="emit('failure',$event)"/><div v-if="files.length" class="evidence"><strong>{{state.correctionOpen?'本次更正佐证材料（可选）':'首次核实佐证材料（可选）'}}</strong><label v-for="f in files" :key="f.id"><input type="checkbox" :checked="evidence.includes(f.id)" :disabled="blocked||!!state.review||!writable||state.detail.verificationStatus==='verified'&&!state.correctionOpen" @change="toggleEvidence(f.id)"/>{{f.fileName}}</label></div></section><p v-else class="muted">先保存草稿后，可上传和选取佐证附件；没有附件也可按规则核实。</p>
    <div v-if="draftWritable" class="actions save-actions"><button :disabled="blocked||!!state.review" @click="safely(()=>controller.save())">保存草稿</button><button class="primary" :disabled="blocked||dirty||!state.detail||!!state.review" @click="guard(()=>controller.reviewVerification())">核实并纳入台账</button><span class="muted">{{dirty||!state.detail?'请先保存草稿再复核。':'复核后明确确认，不会直接入账。'}}</span></div>
   </div><aside class="inspector"><h3>核实及指标范围</h3><p>{{coverage.message}}</p><p>{{coverage.allMissing?'明确全部缺货：核实后不建立应收。':'逐行结果未知不阻止符合条件的历史单核实；需求和最终金额仍正常纳入。'}}</p><template v-if="state.detail?.receivable"><dl><dt>当前有效应收</dt><dd>{{state.detail.receivable.amount}} 元</dd><dt>当前有效已收</dt><dd>{{state.detail.receivable.paid}} 元</dd><dt>当前未收余额</dt><dd>{{state.detail.receivable.balance}} 元</dd><dt>当前到期日</dt><dd>{{state.detail.receivable.dueDate}}</dd></dl></template><p v-else>{{state.detail?.verificationStatus==='verified'?'明确全部缺货，无应收。':'尚未核实，不纳入正式应收、提醒及统计。'}}</p><template v-if="state.detail"><h4>系统留痕</h4><p>补录人 {{state.detail.createdBy}}<br/>补录时间 {{state.detail.createdAt}}<br/>核实人 {{state.detail.verifiedBy||'尚未核实'}}<br/>核实时间 {{state.detail.verifiedAt||'—'}}</p></template></aside></div>
   <section v-if="state.detail?.verificationStatus==='verified'" class="audit"><div class="section-heading"><h3>金额录入更正与完整记录</h3><button v-if="writable&&state.detail.receivable&&!state.correctionOpen" :disabled="blocked" @click="safely(()=>controller.beginCorrection())">读取最新已收，发起金额更正</button></div><p>原核实金额 {{state.detail.originalVerifiedAmount}} 元；首次核实依据、核实人及时间保留。金额更正仅用于录入错误，不执行实际退款。</p><div v-if="state.correctionOpen" class="correction-form"><div class="form-grid"><label>更正后金额 / 元 *<input v-model="state.correction.newAmount" inputmode="decimal" :disabled="blocked||!!state.review"/></label><label>更正原因 *<textarea v-model="state.correction.reason" maxlength="500" :disabled="blocked||!!state.review"></textarea></label></div><p class="muted">已读取有效已收 {{state.detail.receivable?.paid}} 元；提交时服务端再次核对。{{state.correction.newAmount?'请在复核中确认新余额。':''}}</p><label>本次独立核实依据 *<textarea v-model="state.correction.verificationBasis" maxlength="2000" :disabled="blocked||!!state.review"></textarea></label><label>本次独立核实说明 *<textarea v-model="state.correction.verificationNote" maxlength="2000" :disabled="blocked||!!state.review"></textarea></label><button class="primary" :disabled="blocked||!!state.review" @click="guard(()=>controller.reviewCorrection())">复核本次金额更正</button></div><article v-for="change in state.detail.corrections" :key="change.id"><strong>{{change.beforeAmount}} → {{change.afterAmount}} 元</strong><p>原核实 {{change.originalVerifiedAmount}} 元 · 当时有效已收 {{change.paidAtCorrection}} 元 · 更正后余额 {{moneyDifference(change.afterAmount,change.paidAtCorrection)}} 元</p><p>原因：{{change.reason}}</p><p>本次核实依据：{{change.verificationBasis}}</p><p>本次核实说明：{{change.verificationNote}}</p><small>{{change.recordedByName}} · {{change.recordedAt}} · 附件 {{change.evidenceFileIds.length}} 份</small></article><p v-if="!state.detail.corrections.length" class="muted">尚无金额更正记录。</p></section>
   <section v-if="state.detail&&draftWritable" class="void-section"><h3>作废未核实历史草稿</h3><label>作废原因<textarea v-model="state.voidReason" maxlength="500" :disabled="blocked||!!state.review"></textarea></label><button :disabled="blocked||!!state.review" @click="guard(()=>controller.reviewVoid())">复核作废</button></section>
  </template>
  <div v-if="state.review" class="review-overlay"><section class="review-dialog" role="dialog" aria-modal="true" aria-labelledby="historical-review-title"><p class="eyebrow">提交前复核</p><h2 id="historical-review-title">{{state.review.title}}</h2><dl class="review-facts"><template v-for="(fact,i) in state.review.facts" :key="i"><dt>{{fact[0]}}</dt><dd>{{fact[1]}}</dd></template></dl><p class="notice">{{state.review.impact}}</p><label class="ack"><input v-model="ack" type="checkbox" :disabled="busy"/>已核对本次事实、金额及未知范围，确认提交。</label><div class="actions"><button :disabled="busy" @click="state.review=null">返回修改</button><button class="primary" :disabled="blocked||!ack" @click="commit">{{state.working?'正在提交…':'确认提交'}}</button></div></section></div>
  <p class="footnote">本页使用真实业务接口；微信真机操作、真实 COS 配置及外部环境验收仍待完成。</p>
 </div>
